@js:(function(){
 var h = '' + result;
 function clean(t) {
 t = '' + t;
 t = t.replace(/&(?:#8203|#8204|#8205|#8206|#8207|#65279|#xfeff|zwnj|zwj|lrm|rlm);/gi, '');
 t = t.replace(/[\u200b-\u200f\u2060\ufeff]/g, '');
 t = t.replace(/<p[^>]*>[^<]*(?:Loading|\u672a\u52a0\u8f7d\u5b8c|\u5c1d\u8bd5\u66f4\u6362|\u79fb\u52a8\u6d41\u91cf|\u6536\u85cf\u7f51\u5740|\uff1e\u4eba\uff1c)[^<]*<\/p>/g, '');
 return t;
 }
 var m = /\.html\(d\("([\s\S]*?)"\s*,\s*"([0-9a-fA-F]+)"\)/.exec(h);
 if (m) {
 var ct = m[1].replace(/\\\//g, '/');
 try {
 var b = '' + java.md5Encode(m[2]);
 var pt = '' + java.createSymmetricCrypto('AES/CBC/PKCS5Padding', b.substring(16), b.substring(0, 16)).decryptStr(ct);
 return clean(pt);
 } catch (e) {}
 }
 var d = /<div[^>]*class="RBGsectionThree-content"[^>]*>([\s\S]*?)<\/div>/.exec(h);
 if (d) { return clean(d[1]); }
 return '';
})()

