@js:(function(){
 var h = '' + result;
 var m = /<a[^>]*href="([^"]+)"[^>]*id="end"/.exec(h);
 if (!m) { m = /<a[^>]*id="end"[^>]*href="([^"]+)"/.exec(h); }
 if (!m) { return []; }
 var n = /(\d+)\.html/.exec(m[1]);
 if (!n) { return []; }
 var last = parseInt(n[1], 10);
 var cur = 1;
 var bm = /catalog\/(\d+)\.html/.exec('' + baseUrl);
 if (bm) { cur = parseInt(bm[1], 10); }
 var t = '' + book.tocUrl;
 var pages = [];
 for (var i = cur + 1; i <= last; i++) { pages.push(t + i + '.html'); }
 return pages;
})()

