@js:var pageUrl = String(baseUrl);
function inspectPage(markup) {
    java.setContent(String(markup), pageUrl);
    var documents = java.getElements('@css:html');
    if (documents.size() === 0) throw new Error('没有取得网页，请刷新本章');
    var doc = documents.get(0);
    var chapterBox = doc.select('.chapter_box').first();
    var contentBox = doc.select('.chapter_content_box').first();
    var paragraphs = doc.select('.chapter_content_box > p');
    var code = chapterBox === null ? '' : String(chapterBox.attr('data-code'));
    var notice = String(contentBox === null ? doc.text() : contentBox.text()).replace(/\s+/g, '');
    var captcha = /系统检测到.{0,15}访问异常|输入验证码后可继续访问/.test(notice)
        || doc.select('#captcha_btn,[onclick*=toggleCode]').size() > 0;
    var restricted = code !== '' && code !== '0';
    return {doc: doc, paragraphs: paragraphs, count: paragraphs.size(), code: code, captcha: captcha, restricted: restricted};
}
var state = inspectPage(result);
java.log('搬山人正文检查：段落=' + state.count + '，状态=' + state.code + '，验证提示=' + state.captcha);
if (state.captcha || state.restricted || state.count === 5) {
    if (typeof java.startBrowserAwait !== 'function') {
        throw new Error('本章疑似受限预览（' + state.count + '段）。请在阅读内置浏览器打开本章原网页完成验证；当前版本不支持自动验证窗口。');
    }
    var verified = java.startBrowserAwait(pageUrl, '请验证并确认本章正文已完整显示，再点右上角完成', false);
    if (verified === null) throw new Error('没有取得验证后的网页，请重新打开本章原网页');
    state = inspectPage(String(verified.body()));
    java.log('搬山人验证后检查：段落=' + state.count + '，状态=' + state.code + '，验证提示=' + state.captcha);
    if (state.captcha || state.restricted) {
        throw new Error('原网页仍限制本章访问（状态=' + state.code + '，' + state.count + '段）。请完成验证码或网站要求的登录后再试。');
    }
    if (state.count === 5) {
        throw new Error('验证后的网页仍只有5段，已停止保存，避免再次缓存截断内容。请检查原网页是否完整；恰好5段的真实短章也会触发此检查。');
    }
}
if (state.count === 0) throw new Error('网页未提供正文段落，请在原网页检查访问状态');
var clean = state.paragraphs.clone();
clean.select('span[onclick^=togglePostComment],span[class*=count_]').remove();
String(clean.outerHtml());

